import{_ as l,a0 as o,w as p,s as h,ao as d,I as n,x as i,a1 as t,A as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const S=JSON.parse('{"title":"如何 SSH 登录到 Linux 上的特定目录 | LCTT x X-CMD","titleTemplate":false,"description":"如何 SSH 登录到 Linux 上的特定目录 | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何 SSH 登录到 Linux 上的特定目录 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何 SSH 登录到 Linux 上的特定目录 | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20190226 How To SSH Into A Particular Directory On Linux","title":"如何 SSH 登录到 Linux 上的特定目录","tag":"201903","desc":""},"relativePath":"201903/20190226 How To SSH Into A Particular Directory On Linux.md","filePath":"[post].md"}'),r={name:"201903/20190226 How To SSH Into A Particular Directory On Linux.md"};function c(g,s,k,u,b,m){const e=o("Link");return p(),h("div",null,[s[15]||(s[15]=d('<h1 id="如何-ssh-登录到-linux-上的特定目录" tabindex="-1">如何 SSH 登录到 Linux 上的特定目录 <a class="header-anchor" href="#如何-ssh-登录到-linux-上的特定目录" aria-label="Permalink to “如何 SSH 登录到 Linux 上的特定目录”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/02/SSH-Into-A-Particular-Directory-720x340.png" alt=""></p><p>你是否遇到过需要 SSH 登录到远程服务器并立即 <code>cd</code> 到一个目录来继续交互式作业？你找对地方了！这个简短的教程描述了如何直接 SSH 登录到远程 Linux 系统的特定目录。而且不仅是 SSH 登录到特定目录，你还可以在连接到 SSH 服务器后立即运行任何命令。这些没有你想的那么难。请继续阅读。</p><h3 id="ssh-登录到远程系统的特定目录" tabindex="-1">SSH 登录到远程系统的特定目录 <a class="header-anchor" href="#ssh-登录到远程系统的特定目录" aria-label="Permalink to “SSH 登录到远程系统的特定目录”">​</a></h3><p>在我知道这个方法之前，我通常首先使用以下命令 SSH 登录到远程系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh user@remote-system</span></span></code></pre></div><p>然后如下 <code>cd</code> 进入某个目录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cd &lt;some-directory&gt;</span></span></code></pre></div><p>然而，你不需要使用两个单独的命令。你可以用一条命令组合并简化这个任务。</p><p>看看下面的例子。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -t sk@192.168.225.22 &#39;cd /home/sk/ostechnix ; bash&#39;</span></span></code></pre></div><p>上面的命令将通过 SSH 连接到远程系统 （192.168.225.22） 并立即进入名为 <code>/home/sk/ostechnix/</code> 的目录，并停留在提示符中。</p><p>这里，<code>-t</code> 标志用于强制分配伪终端，这是一个必要的交互式 shell。</p><p>以下是上面命令的输出：</p><p><img src="https://www.ostechnix.com/wp-content/uploads/2019/02/ssh-1.gif" alt=""></p><p>你也可以使用此命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -t sk@192.168.225.22 &#39;cd /home/sk/ostechnix ; exec bash&#39;</span></span></code></pre></div><p>或者，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -t sk@192.168.225.22 &#39;cd /home/sk/ostechnix &amp;&amp; exec bash -l&#39;</span></span></code></pre></div><p>这里，<code>-l</code> 标志将 bash 设置为登录 shell。</p><p>在上面的例子中，我在最后一个参数中使用了 <code>bash</code>。它是我的远程系统中的默认 shell。如果你不知道远程系统上的 shell 类型，请使用以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -t sk@192.168.225.22 &#39;cd /home/sk/ostechnix &amp;&amp; exec $SHELL&#39;</span></span></code></pre></div><p>就像我已经说过的，它不仅仅是连接到远程系统后 <code>cd</code> 进入目录。你也可以使用此技巧运行其他命令。例如，以下命令将进入 <code>/home/sk/ostechnix/</code>，然后执行命令 <code>uname -a</code> 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh -t sk@192.168.225.22 &#39;cd /home/sk/ostechnix &amp;&amp; uname -a &amp;&amp; exec $SHELL&#39;</span></span></code></pre></div><p>或者，你可以在远程系统上的 <code>.bash_profile</code> 文件中添加你想在 SSH 登录后执行的命令。</p><p>编辑 <code>.bash_profile</code> 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ nano ~/.bash_profile</span></span></code></pre></div><p>每个命令一行。在我的例子中，我添加了下面这行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>cd /home/sk/ostechnix &gt;&amp; /dev/null</span></span></code></pre></div><p>保存并关闭文件。最后，运行以下命令更新修改。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ source ~/.bash_profile</span></span></code></pre></div><p>请注意，你应该在远程系统的 <code>.bash_profile</code> 或 <code>.bashrc</code> 文件中添加此行，而不是在本地系统中。从现在开始，无论何时登录（无论是通过 SSH 还是直接登录），<code>cd</code> 命令都将执行，你将自动进入 <code>/home/sk/ostechnix/</code> 目录。</p><p>就是这些了。希望这篇文章有用。还有更多好东西。敬请关注！</p><p>干杯!</p><hr>',35)),n("p",null,[s[1]||(s[1]=i("via: ",-1)),t(e,{href:"https://www.ostechnix.com/how-to-ssh-into-a-particular-directory-on-linux/"},{default:a(()=>[...s[0]||(s[0]=[i("https://www.ostechnix.com/how-to-ssh-into-a-particular-directory-on-linux/",-1)])]),_:1})]),n("p",null,[s[6]||(s[6]=i("作者：",-1)),t(e,{href:"https://www.ostechnix.com/author/sk/"},{default:a(()=>[...s[2]||(s[2]=[i("SK",-1)])]),_:1}),s[7]||(s[7]=i(" 选题：",-1)),t(e,{href:"https://github.com/lujun9972"},{default:a(()=>[...s[3]||(s[3]=[i("lujun9972",-1)])]),_:1}),s[8]||(s[8]=i(" 译者：",-1)),t(e,{href:"https://github.com/geekpi"},{default:a(()=>[...s[4]||(s[4]=[i("geekpi",-1)])]),_:1}),s[9]||(s[9]=i(" 校对：",-1)),t(e,{href:"https://github.com/wxy"},{default:a(()=>[...s[5]||(s[5]=[i("wxy",-1)])]),_:1})]),n("p",null,[s[12]||(s[12]=i("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...s[10]||(s[10]=[i("LCTT",-1)])]),_:1}),s[13]||(s[13]=i(" 原创编译，",-1)),t(e,{href:"https://linux.cn/"},{default:a(()=>[...s[11]||(s[11]=[i("Linux中国",-1)])]),_:1}),s[14]||(s[14]=i(" 荣誉推出",-1))])])}const y=l(r,[["render",c]]);export{S as __pageData,y as default};
